Copy the input workbook to the output path and read cached values from Base and Streets. For each Base row, search Streets for a case-insensitive street match with populated numeric Start/End that contains the Base number, taking the first such row. Write the corresponding Streets F value (or an empty string) into Base E2:E26 and save.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

base_v = vals["Base"]
streets_v = vals["Streets"]
ws = wb["Base"]

def clean_text(v):
    if v is None:
        return ""
    return str(v).strip()

def to_number(v):
    if isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        try:
            return float(s)
        except ValueError:
            return None
    return None

streets = []
for r in range(2, streets_v.max_row + 1):
    street = clean_text(streets_v.cell(row=r, column=2).value)
    start = to_number(streets_v.cell(row=r, column=3).value)
    end = to_number(streets_v.cell(row=r, column=4).value)
    name = clean_text(streets_v.cell(row=r, column=6).value)

    if street and start is not None and end is not None:
        lo, hi = (start, end) if start <= end else (end, start)
        streets.append((street.lower(), lo, hi, name))

for r in range(2, 27):
    street = clean_text(base_v.cell(row=r, column=3).value)
    number = to_number(base_v.cell(row=r, column=4).value)
    result = ""

    if street and number is not None:
        key = street.lower()
        for skey, lo, hi, name in streets:
            if skey == key and lo <= number <= hi:
                result = name
                break

    ws.cell(row=r, column=5).value = result

print("valid_streets", len(streets))
print("sample", [(r, ws.cell(row=r, column=5).value) for r in range(2, 12)])

wb.save(OUT)
